// serviceAssertNamedZeroOnError asserts Named returns zero alongside any error.
func serviceAssertNamedZeroOnError(
	tb testing.TB,
	s Service,
	fx ServiceFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := s.Named(ctx, fx.ID())
	if err == nil {
		tb.Skip("Named answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("Named must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

